/**
 * @file bicycle_inval_probe.h
 * @brief 自行车 UI — inval_probe。
 */

#ifndef BICYCLE_INVAL_PROBE_H
#define BICYCLE_INVAL_PROBE_H

#include "lvgl/lvgl.h"

#ifdef __cplusplus
extern "C" {
#endif

/**
