#define INV_HIST_N 12
typedef struct {
    const char * tag;
    int32_t w;
    int32_t h;
    uint32_t n;
    uint64_t px;
} inv_hist_t;
static inv_hist_t s_obj_hist[INV_HIST_N];
static inv_hist_t s_area_hist[INV_HIST_N];

static void inv_hist_add(inv_hist_t * hist, const char * tag, int32_t w, int32_t h)
{
    int i;
    int slot = -1;

    for (i = 0; i < INV_HIST_N; i++) {
        if (hist[i].n == 0u || (hist[i].tag == tag && hist[i].w == w && hist[i].h == h)) {
            slot = i;
            break;
        }
    }
    if (slot < 0) {
        return;                       /* 满了就丢，不覆盖，保前 12 个 */
    }
    hist[slot].tag = tag;
    hist[slot].w = w;
    hist[slot].h = h;
    hist[slot].n++;
    hist[slot].px += (uint64_t)(w > 0 ? w : 0) * (uint64_t)(h > 0 ? h : 0);
}

static void inv_hist_dump(const char * what, inv_hist_t * hist)
{
    int i;

    for (i = 0; i < INV_HIST_N; i++) {
