/**
 * @brief 移动对象但把"旧位置+新位置"四次失效合并成一次。
 *
 * `lv_obj_set_pos()` 内部先 set_x 再 set_y，每次都会失效旧/新矩形 —— 一次平移
 * 触发 4 条 496x472 失效（WP-OPT1 探针实测：每帧 6 次平移 = 24 条失效）。
 * 画布比视口大一圈（overscan），旧/新可见区完全重合，4 条失效合并后仍是同一个
 * 视口矩形，所以这里关掉失效、挪完再按一次失效上屏，像素结果不变。
 */
static void canvas_move_coalesced(lv_obj_t * obj, lv_coord_t x, lv_coord_t y)
{
    lv_display_t * disp;

    if (obj == NULL) {
        return;
    }

    disp = lv_obj_get_display(obj);
    if (disp != NULL) {
        lv_display_enable_invalidation(disp, false);
        lv_obj_set_pos(obj, x, y);
        lv_display_enable_invalidation(disp, true);
    } else {
        lv_obj_set_pos(obj, x, y);
    }

    lv_obj_invalidate(obj);
}
