static double pt_seg_dist2(double ax, double ay, double bx, double by, double cx,
    double cy)
{
    const double dx = cx - ax;
    const double dy = cy - ay;
    const double len2 = dx * dx + dy * dy;
    double t;
    double px;
    double py;
    double ex;
    double ey;

    if (len2 < 1e-6) {
        ex = bx - ax;
        ey = by - ay;
        return ex * ex + ey * ey;
    }

    t = ((bx - ax) * dx + (by - ay) * dy) / len2;
    if (t < 0.0) {
        t = 0.0;
    } else if (t > 1.0) {
        t = 1.0;
    }

    px = ax + t * dx;
    py = ay + t * dy;
    ex = bx - px;
    ey = by - py;
    return ex * ex + ey * ey;
}

