{"command": "cd /home/jinsc/SDK/vela/openvela/vendor/my_vendor/boards/sf32lb52/my_vendor/ui/bicycle/src/vmap && python3 - <<'PY'
p='vmap_render.c'
s=open(p).read()

# ---- RDP: pt_seg_dist2 + vmap_render_simplify_polyline ----
start = s.index('static double pt_seg_dist2(double ax, double ay, double bx, double by, double cx,')
end = s.index('#if VMAP_ROAD_SIMPLIFY', start)
new = '''static float pt_seg_dist2(float ax, float ay, float bx, float by, float cx,
    float cy)
{
    const float dx = cx - ax;
    const float dy = cy - ay;
    const float len2 = dx * dx + dy * dy;
    float t;
    float px;
    float py;
    float ex;
    float ey;

    if (len2 < 1e-6f) {
        ex = bx - ax;
        ey = by - ay;
        return ex * ex + ey * ey;
    }

    t = ((bx - ax) * dx + (by - ay) * dy) / len2;
    if (t < 0.0f) {
        t = 0.0f;
    } else if (t > 1.0f) {
        t = 1.0f;
    }

    px = ax + t * dx;
    py = ay + t * dy;
    ex = bx - px;
    ey = by - py;
    return ex * ex + ey * ey;
}

/**
 * @brief Douglas-Peucker 简化折线。
 * @param pts 点数组。
 * @param n 点数。
 */
int32_t vmap_render_simplify_polyline(vmap_point_t * pts, int32_t n,
    float min_seg_px, float max_dev_px)
{
    const float min_seg2 = min_seg_px * min_seg_px;
    const float max_dev2 = max_dev_px * max_dev_px;
    int32_t w;

    if (n < 3) {
        return n;
    }

    w = 1;
    for (int32_t i = 1; i < n - 1; i++) {
        const float dev2 = pt_seg_dist2((float)pts[w - 1].x, (float)pts[w - 1].y,
            (float)pts[i].x, (float)pts[i].y,
            (float)pts[i + 1].x, (float)pts[i + 1].y);
        const float dx = (float)pts[i].x - (float)pts[w - 1].x;
        const float dy = (float)pts[i].y - (float)pts[w - 1].y;
        const float seg2 = dx * dx + dy * dy;

        if (dev2 < max_dev2) {
            continue;
        }

        if (seg2 < min_seg2) {
            pts[w - 1] = pts[i];
        } else {
            pts[w++] = pts[i];
        }
    }

    {
        const float dx = (float)pts[n - 1].x - (float)pts[w - 1].x;
        const float dy = (float)pts[n - 1].y - (float)pts[w - 1].y;

        if (dx * dx + dy * dy < min_seg2 && w >= 2) {
            pts[w - 1] = pts[n - 1];
        } else {
            pts[w++] = pts[n - 1];
        }
    }

    return w;
}

